for _,e in ipairs(HeroCompanionBundles)do add(e);HeroBrowseAssignment[e.id]={categories={23},order=0,direct=true}end
for _,e in ipairs(HeroCompanionAbilities)do add(e);HeroBrowseAssignment[e.id]={categories={23},order=0,direct=true}end
local replaced={}
for _,e in ipairs(HeroCompanionAbilities)do replaced[e.spells[1]]=true end
function A.EntryAvailableInMode(e)
 if A.mode=='Classic'then return e.id<20000000 and not e.isMastery and not A.OtherClass(e.class)end
 if not e.isBundle and not e.requiredBundle and not A.IsTalent(e)then
  for _,spell in ipairs(e.spells)do if replaced[spell]then return false end end
 end
 return true
end
local results=A.Results
function A.Results()
 local out={};for _,e in ipairs(results())do if A.EntryAvailableInMode(e)then out[#out+1]=e end end;return out
end
-- A bundle owns its preview grants: children cannot be purchased/refunded independently.
local function bundleSetter(original,key)
 return function(id,rank)
  local e=A.byID[id]
  if e and e.requiredBundle then
   A.ShowPointWarning('Included with '..A.byID[e.requiredBundle].name..'. Add or remove the bundle instead.');return false
  end
  if e and not A.EntryAvailableInMode(e)then return false end
  if e and e.isBundle and A.mode~='Classic'then
   if not original(id,rank)then return false end
   local state=HeroFreePickPlans[key]
   for _,child in ipairs(HeroCompanionAbilities)do if child.requiredBundle==id then state[child.id]=state[id]and 1 or nil end end
   -- Replace old independently planned versions in custom modes only.
   if state[id]then
    for oldID in pairs(state)do local old=A.byID[oldID]
     if old and not old.requiredBundle and not old.isBundle and not A.IsTalent(old)then
      for _,spell in ipairs(old.spells)do for _,member in ipairs(e.members)do if spell==member then state[oldID]=nil end end end
     end
    end
   end
   return true
  end
  return original(id,rank)
 end
end
A.SetRank=bundleSetter(A.SetRank,'entries')
A.SetLocalLearned=bundleSetter(A.SetLocalLearned,'previewLearned')
